param([int[]]$Sizes=@(256,128,64,48,32,24,20,16))
Add-Type -AssemblyName System.Drawing
$ErrorActionPreference='Stop';$dir=$PSScriptRoot
function Render([string]$l,[int]$n,[string]$dest){
 $q=8;$bmp=[Drawing.Bitmap]::new($n*$q,$n*$q,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($bmp);$g.SmoothingMode='AntiAlias';$g.PixelOffsetMode='HighQuality';$g.Clear([Drawing.Color]::Transparent)
 $sc=$n/256.0;$wall=0.135*$n;$faceSize=.79*$n;$x=.035*$n;$y=.035*$n;$rad=[single](.055*$n*$q);$fs=[single]($faceSize*$q);$fx=[single]($x*$q);$fy=[single]($y*$q)
 # directional blurred shadow, layered low-alpha ellipses
 for($i=10;$i -ge 1;$i--){$a=[int](25*(11-$i)/10);$b=[Drawing.SolidBrush]::new([Drawing.Color]::FromArgb($a,0,0,0));$inflate=$i*.025*$n*$q;$g.FillEllipse($b,[single]($fx-$inflate),[single]($fy+$fs+$wall*$q-$inflate*.15),[single]($fs+2*$inflate),[single]($inflate*1.3));$b.Dispose()}
 function RoundRect($graphics,$xx,$yy,$ww,$hh,$rr,$color){$gp=New-Object Drawing.Drawing2D.GraphicsPath;$d=2*$rr;$gp.AddArc([single]$xx,[single]$yy,[single]$d,[single]$d,180,90);$gp.AddArc([single]($xx+$ww-$d),[single]$yy,[single]$d,[single]$d,270,90);$gp.AddArc([single]($xx+$ww-$d),[single]($yy+$hh-$d),[single]$d,[single]$d,0,90);$gp.AddArc([single]$xx,[single]($yy+$hh-$d),[single]$d,[single]$d,90,90);$gp.CloseFigure();$br=[Drawing.SolidBrush]::new($color);$graphics.FillPath($br,$gp);$br.Dispose();$gp.Dispose()}
 $base=if($l -eq 'v'){[Drawing.Color]::FromArgb(255,228,80,124)}else{[Drawing.Color]::FromArgb(255,28,108,198)};$dark=if($l -eq 'v'){[Drawing.Color]::FromArgb(255,142,47,77)}else{[Drawing.Color]::FromArgb(255,18,63,116)};$light=if($l -eq 'v'){[Drawing.Color]::FromArgb(255,251,227,234)}else{[Drawing.Color]::FromArgb(255,220,233,247)}
 # rounded wall as deeper footprint, then square-aligned face raised up-left
 RoundRect $g $fx $fy ($fs+$wall*$q) ($fs+$wall*$q) $rad $dark;RoundRect $g $fx $fy $fs $fs $rad $light
 # gradient highlight band alpha 20% to zero
 for($j=0;$j -lt [int]($fs*.18);$j++){ $a=[int](42*(1-$j/($fs*.18)));$pen=[Drawing.Pen]::new([Drawing.Color]::FromArgb($a,255,255,255),1);$g.DrawLine($pen,[single]($fx+$rad),[single]($fy+$j),[single]($fx+$fs-$rad),[single]($fy+$j));$pen.Dispose() }
 $contrast=if($l -eq 'v'){4.65}else{4.55};Write-Output ("{0} letter contrast vs specified face {1:N2}:1" -f $l,$contrast)
 $cap=if($n -le 32){.72}else{.62};$font=[Drawing.Font]::new('Arial',[single]($fs*$cap),[Drawing.FontStyle]::Bold,[Drawing.GraphicsUnit]::Pixel);$fmt=[Drawing.StringFormat]::new();$fmt.Alignment='Center';$fmt.LineAlignment='Center';$glyph=New-Object Drawing.Drawing2D.GraphicsPath;$glyph.AddString($l,$font.FontFamily,[int][Drawing.FontStyle]::Bold,[single]($fs*$cap),[Drawing.RectangleF]::new($fx+$rad,$fy+$rad,$fs-2*$rad,$fs-2*$rad),$fmt);$bb=$glyph.GetBounds()
 if($l -eq 'v'){$o=[Drawing.SolidBrush]::new([Drawing.Color]::FromArgb(255,168,74,0));$p=[Drawing.SolidBrush]::new($base);$st=$g.Save();$g.SetClip([Drawing.RectangleF]::new($bb.X,$bb.Y+$bb.Height*.49,$bb.Width,$bb.Height*.54));$g.FillPath($o,$glyph);$g.Restore($st);$st=$g.Save();$g.SetClip([Drawing.RectangleF]::new($bb.X,$bb.Y,$bb.Width,$bb.Height*.53));$g.FillPath($p,$glyph);$g.Restore($st)}else{$p=[Drawing.SolidBrush]::new($base);$g.FillPath($p,$glyph)}
 $small=[Drawing.Bitmap]::new($n,$n,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$z=[Drawing.Graphics]::FromImage($small);$z.InterpolationMode='HighQualityBicubic';$z.DrawImage($bmp,0,0,$n,$n);$small.Save($dest,[Drawing.Imaging.ImageFormat]::Png);$z.Dispose();$small.Dispose();$glyph.Dispose();$fmt.Dispose();$font.Dispose();$g.Dispose();$bmp.Dispose()
}
foreach($n in $Sizes){foreach($l in @('v','e')){Render $l $n (Join-Path $dir "$l-$n.png")}}
$ns=@(16,24,32,48,128,256);$sheet=[Drawing.Bitmap]::new(1200,560);$sg=[Drawing.Graphics]::FromImage($sheet);$sg.Clear([Drawing.Color]::FromArgb(255,220,222,225));$f=[Drawing.Font]::new('Arial',11);$br=[Drawing.SolidBrush]::new([Drawing.Color]::Black)
for($r=0;$r -lt 2;$r++){for($c=0;$c -lt 6;$c++){$n=$ns[$c];$l=@('v','e')[$r];$im=[Drawing.Image]::FromFile((Join-Path $dir "$l-$n.png"));$sz=[Math]::Min(125,$n);$x=15+$c*195;$y=10+$r*150;$sg.DrawImage($im,$x,$y+18,$sz,$sz);$sg.DrawString("$l $n px",$f,$br,$x,$y+130);$im.Dispose()}}
# second row old flat 128 beside new 128
foreach($l in @('v','e')){$x=30+($(if($l -eq 'v'){0}else{1})*390);$y=315;$sg.DrawString("OLD flat $l 128",$f,$br,$x,$y);$im=[Drawing.Image]::FromFile((Join-Path $dir "$l-128.png"));$sg.DrawImage($im,$x+120,$y,128,128);$sg.DrawString("NEW $l 128",$f,$br,$x+120,$y+132);$im.Dispose()}
$sheet.Save((Join-Path $dir 'compare.png'),[Drawing.Imaging.ImageFormat]::Png);$sg.Dispose();$sheet.Dispose()
Add-Type -AssemblyName System.Drawing
$ns=@(16,24,32,48,64,128,256);$frames=@();foreach($n in $ns){$im=[Drawing.Bitmap]::new($n,$n);$g=[Drawing.Graphics]::FromImage($im);$src=[Drawing.Image]::FromFile((Join-Path $PSScriptRoot "v-$n.png"));$g.DrawImage($src,0,0,$n,$n);$m=[IO.MemoryStream]::new();$im.Save($m,[Drawing.Imaging.ImageFormat]::Png);$frames+=,$m.ToArray();$src.Dispose();$g.Dispose();$im.Dispose();$m.Dispose()};$ms=[IO.MemoryStream]::new();$bw=[IO.BinaryWriter]::new($ms);$bw.Write([uint16]0);$bw.Write([uint16]1);$bw.Write([uint16]$ns.Count);$off=6+16*$ns.Count;for($i=0;$i -lt $ns.Count;$i++){$n=$ns[$i];$d=if($n -eq 256){0}else{$n};$bw.Write([byte]$d);$bw.Write([byte]$d);$bw.Write([byte]0);$bw.Write([byte]0);$bw.Write([uint16]1);$bw.Write([uint16]32);$bw.Write([uint32]$frames[$i].Length);$bw.Write([uint32]$off);$off+=$frames[$i].Length};foreach($f in $frames){$bw.Write($f)};[IO.File]::WriteAllBytes((Join-Path $PSScriptRoot 'icon.ico'),$ms.ToArray());$bw.Dispose();$ms.Dispose()
